create table xxcus.xxfnd_transmissions (
    transmission_id      number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    endpoint_code        varchar2(30 byte) not null enable,
    purpose_code         varchar2(30 byte) not null enable,
    entity_name          varchar2(60 byte),
    pk1_value            varchar2(150 byte),
    http_method          varchar2(10 byte) not null enable,
    request_url          varchar2(4000 byte) not null enable,
    request_payload      clob,
    response_status_code number(3, 0),
    response_payload     clob,
    status_code          varchar2(20 byte) default 'PENDING' not null enable,
    retry_count          number(3, 0) default 0 not null enable,
    error_message        varchar2(4000 byte),
    sent_date            timestamp(6) default systimestamp not null enable,
    responded_date       timestamp(6),
    created_by           varchar2(255 byte) not null enable
);

alter table xxcus.xxfnd_transmissions
    add constraint xxfnd_transmissions_ck1
        check ( status_code in ( 'PENDING', 'SUCCESS', 'FAILED', 'RETRYING' ) ) enable;

alter table xxcus.xxfnd_transmissions
    add constraint xxfnd_transmissions_pk primary key ( transmission_id )
        using index enable;


